DOMAIN_CONTENT = 'from __future__ import annotations\n\nimport hashlib\nfrom dataclasses import dataclass\nfrom decimal import Decimal\nfrom typing import Any\n\n\nACCOUNT_KINDS = frozenset({"BROKER", "MANUAL", "VIRTUAL"})\nBROKER_ENVIRONMENTS = frozenset({"REAL", "VIRTUAL"})\nACCOUNT_STATUSES = frozenset({"ACTIVE", "ARCHIVED"})\nPOSITION_STATUSES = frozenset({"OPEN", "CLOSED"})\nPOSITION_OPEN_REASONS = frozenset({"MANUAL", "KIS_OBSERVED", "VIRTUAL"})\nPOSITION_EVENT_TYPES = frozenset(\n    {"BUY", "SELL", "CORRECTION", "BALANCE_OBSERVED", "RECONCILED"}\n)\nSYNC_STATUSES = frozenset({"RUNNING", "COMPLETED", "FAILED"})\n\n\ndef account_fingerprint(\n    *,\n    provider: str,\n    broker_environment: str,\n    account_number: str,\n    product_code: str,\n) -> str:\n    """Return a stable identifier without persisting the raw broker account number."""\n    material = "|".join(\n        [\n            provider.strip().upper(),\n            broker_environment.strip().upper(),\n            account_number.strip(),\n            product_code.strip(),\n        ]\n    )\n    return hashlib.sha256(material.encode("utf-8")).hexdigest()\n\n\n@dataclass(frozen=True, slots=True)\nclass PositionAccount:\n    id: str\n    provider: str\n    account_kind: str\n    broker_environment: str | None\n    external_account_fingerprint: str | None\n    display_name: str\n    status: str\n    created_at: str\n    updated_at: str\n\n\n@dataclass(frozen=True, slots=True)\nclass MonitoredStock:\n    id: str\n    market: str\n    ticker: str\n    name: str\n    watch_enabled: bool\n    archived_at: str | None\n    created_at: str\n    updated_at: str\n\n\n@dataclass(frozen=True, slots=True)\nclass AccountSyncRun:\n    id: str\n    position_account_id: str\n    status: str\n    started_at: str\n    completed_at: str | None\n    is_complete: bool\n    observed_at: str | None\n    page_count: int\n    holding_count: int\n    error_code: str | None\n    error_message: str | None\n    created_at: str\n    updated_at: str\n\n\n@dataclass(frozen=True, slots=True)\nclass HoldingPosition:\n    id: str\n    monitored_stock_id: str\n    position_account_id: str\n    status: str\n    opened_at: str\n    closed_at: str | None\n    current_quantity: Decimal\n    current_average_price: Decimal | None\n    current_cost_basis: Decimal | None\n    opened_reason: str\n    last_observed_at: str | None\n    last_sync_run_id: str | None\n    created_at: str\n    updated_at: str\n\n\n@dataclass(frozen=True, slots=True)\nclass HoldingPositionEvent:\n    id: str\n    position_id: str\n    event_type: str\n    quantity_delta: Decimal | None\n    unit_price: Decimal | None\n    before_quantity: Decimal | None\n    after_quantity: Decimal | None\n    before_average_price: Decimal | None\n    after_average_price: Decimal | None\n    observed_at: str | None\n    effective_at: str | None\n    analysis_revision_id: str | None\n    account_sync_run_id: str | None\n    external_event_key: str | None\n    note: str | None\n    created_at: str\n\n\n@dataclass(frozen=True, slots=True)\nclass StockAnalysisDay:\n    id: str\n    monitored_stock_id: str\n    market_date: str\n    current_revision_id: str | None\n    created_at: str\n    updated_at: str\n\n\n@dataclass(frozen=True, slots=True)\nclass StockAnalysisRevision:\n    id: str\n    analysis_day_id: str\n    revision_no: int\n    input_fingerprint: str\n    strategy_key: str | None\n    action_state: str | None\n    risk_state: str | None\n    reference_price: Decimal | None\n    stop_price: Decimal | None\n    target1_price: Decimal | None\n    target2_price: Decimal | None\n    scanner_version: str | None\n    analysis_engine_version: str | None\n    policy_version: str | None\n    source_versions: Any\n    snapshot: Any\n    revision_reason: str | None\n    computed_at: str\n    created_at: str\n'
CATALOG_CONTENT = 'from __future__ import annotations\n\nimport json\nimport re\nimport sqlite3\nfrom datetime import datetime, timezone\nfrom decimal import Decimal, InvalidOperation\nfrom pathlib import Path\nfrom typing import Any\nfrom uuid import uuid4\n\nfrom app.core.config import PROJECT_ROOT\n\nfrom .domain import (\n    ACCOUNT_KINDS,\n    ACCOUNT_STATUSES,\n    BROKER_ENVIRONMENTS,\n    POSITION_EVENT_TYPES,\n    POSITION_OPEN_REASONS,\n    POSITION_STATUSES,\n    SYNC_STATUSES,\n    AccountSyncRun,\n    HoldingPosition,\n    HoldingPositionEvent,\n    MonitoredStock,\n    PositionAccount,\n    StockAnalysisDay,\n    StockAnalysisRevision,\n)\n\n\nDEFAULT_HOLDINGS_DB = PROJECT_ROOT / "backend" / "runtime" / "holdings" / "holdings.db"\n_HEX64 = re.compile(r"^[0-9a-f]{64}$")\n\n\nclass HoldingsCatalogError(RuntimeError):\n    def __init__(self, code: str, message: str):\n        super().__init__(message)\n        self.code = code\n        self.message = message\n\n\ndef _now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef _json_text(value: Any) -> str:\n    return json.dumps(\n        value,\n        ensure_ascii=False,\n        sort_keys=True,\n        separators=(",", ":"),\n        default=str,\n    )\n\n\ndef _json_value(value: str | None) -> Any:\n    if value in (None, ""):\n        return None\n    return json.loads(value)\n\n\ndef _decimal_text(value: Decimal | int | float | str | None) -> str | None:\n    if value is None:\n        return None\n    try:\n        number = value if isinstance(value, Decimal) else Decimal(str(value))\n    except (InvalidOperation, ValueError, TypeError) as exc:\n        raise HoldingsCatalogError(\n            "HOLD_DECIMAL_INVALID",\n            f"유효하지 않은 숫자입니다: {value}",\n        ) from exc\n    if not number.is_finite():\n        raise HoldingsCatalogError("HOLD_DECIMAL_INVALID", "유한한 숫자만 저장할 수 있습니다.")\n    return format(number, "f")\n\n\ndef _decimal_value(value: str | int | float | None) -> Decimal | None:\n    if value is None:\n        return None\n    return Decimal(str(value))\n\n\nclass HoldingsCatalog:\n    def __init__(self, db_path: Path | None = None):\n        self.db_path = Path(db_path or DEFAULT_HOLDINGS_DB)\n\n    def connect(self) -> sqlite3.Connection:\n        self.db_path.parent.mkdir(parents=True, exist_ok=True)\n        conn = sqlite3.connect(self.db_path)\n        conn.row_factory = sqlite3.Row\n        conn.execute("PRAGMA foreign_keys=ON")\n        return conn\n\n    def initialize(self) -> None:\n        with self.connect() as conn:\n            conn.executescript(\n                """\n                CREATE TABLE IF NOT EXISTS position_account (\n                    id TEXT PRIMARY KEY,\n                    provider TEXT NOT NULL,\n                    account_kind TEXT NOT NULL\n                        CHECK(account_kind IN (\'BROKER\',\'MANUAL\',\'VIRTUAL\')),\n                    broker_environment TEXT\n                        CHECK(broker_environment IS NULL OR broker_environment IN (\'REAL\',\'VIRTUAL\')),\n                    external_account_fingerprint TEXT,\n                    display_name TEXT NOT NULL,\n                    status TEXT NOT NULL\n                        CHECK(status IN (\'ACTIVE\',\'ARCHIVED\')),\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL\n                );\n\n                CREATE UNIQUE INDEX IF NOT EXISTS ux_position_account_external\n                    ON position_account(provider, broker_environment, external_account_fingerprint)\n                    WHERE external_account_fingerprint IS NOT NULL;\n\n                CREATE TABLE IF NOT EXISTS monitored_stock (\n                    id TEXT PRIMARY KEY,\n                    market TEXT NOT NULL,\n                    ticker TEXT NOT NULL,\n                    name TEXT NOT NULL,\n                    watch_enabled INTEGER NOT NULL DEFAULT 1\n                        CHECK(watch_enabled IN (0,1)),\n                    archived_at TEXT,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL,\n                    UNIQUE(market, ticker)\n                );\n\n                CREATE TABLE IF NOT EXISTS stock_analysis_day (\n                    id TEXT PRIMARY KEY,\n                    monitored_stock_id TEXT NOT NULL,\n                    market_date TEXT NOT NULL,\n                    current_revision_id TEXT,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL,\n                    UNIQUE(monitored_stock_id, market_date),\n                    FOREIGN KEY(monitored_stock_id)\n                        REFERENCES monitored_stock(id) ON DELETE RESTRICT,\n                    FOREIGN KEY(current_revision_id)\n                        REFERENCES stock_analysis_revision(id) ON DELETE RESTRICT\n                );\n\n                CREATE TABLE IF NOT EXISTS stock_analysis_revision (\n                    id TEXT PRIMARY KEY,\n                    analysis_day_id TEXT NOT NULL,\n                    revision_no INTEGER NOT NULL CHECK(revision_no >= 1),\n                    input_fingerprint TEXT NOT NULL,\n                    strategy_key TEXT,\n                    action_state TEXT,\n                    risk_state TEXT,\n                    reference_price TEXT,\n                    stop_price TEXT,\n                    target1_price TEXT,\n                    target2_price TEXT,\n                    scanner_version TEXT,\n                    analysis_engine_version TEXT,\n                    policy_version TEXT,\n                    source_versions_json TEXT NOT NULL,\n                    snapshot_json TEXT NOT NULL,\n                    revision_reason TEXT,\n                    computed_at TEXT NOT NULL,\n                    created_at TEXT NOT NULL,\n                    UNIQUE(analysis_day_id, revision_no),\n                    UNIQUE(analysis_day_id, input_fingerprint),\n                    FOREIGN KEY(analysis_day_id)\n                        REFERENCES stock_analysis_day(id) ON DELETE RESTRICT\n                );\n\n                CREATE TRIGGER IF NOT EXISTS trg_stock_analysis_revision_no_update\n                BEFORE UPDATE ON stock_analysis_revision\n                BEGIN\n                    SELECT RAISE(ABORT, \'stock_analysis_revision is immutable\');\n                END;\n\n                CREATE TRIGGER IF NOT EXISTS trg_stock_analysis_revision_no_delete\n                BEFORE DELETE ON stock_analysis_revision\n                BEGIN\n                    SELECT RAISE(ABORT, \'stock_analysis_revision is immutable\');\n                END;\n\n                CREATE TABLE IF NOT EXISTS account_sync_run (\n                    id TEXT PRIMARY KEY,\n                    position_account_id TEXT NOT NULL,\n                    status TEXT NOT NULL\n                        CHECK(status IN (\'RUNNING\',\'COMPLETED\',\'FAILED\')),\n                    started_at TEXT NOT NULL,\n                    completed_at TEXT,\n                    is_complete INTEGER NOT NULL DEFAULT 0\n                        CHECK(is_complete IN (0,1)),\n                    observed_at TEXT,\n                    page_count INTEGER NOT NULL DEFAULT 0 CHECK(page_count >= 0),\n                    holding_count INTEGER NOT NULL DEFAULT 0 CHECK(holding_count >= 0),\n                    error_code TEXT,\n                    error_message TEXT,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL,\n                    FOREIGN KEY(position_account_id)\n                        REFERENCES position_account(id) ON DELETE RESTRICT\n                );\n\n                CREATE INDEX IF NOT EXISTS idx_account_sync_run_account_started\n                    ON account_sync_run(position_account_id, started_at DESC);\n\n                CREATE TABLE IF NOT EXISTS holding_position (\n                    id TEXT PRIMARY KEY,\n                    monitored_stock_id TEXT NOT NULL,\n                    position_account_id TEXT NOT NULL,\n                    status TEXT NOT NULL CHECK(status IN (\'OPEN\',\'CLOSED\')),\n                    opened_at TEXT NOT NULL,\n                    closed_at TEXT,\n                    current_quantity TEXT NOT NULL,\n                    current_average_price TEXT,\n                    current_cost_basis TEXT,\n                    opened_reason TEXT NOT NULL\n                        CHECK(opened_reason IN (\'MANUAL\',\'KIS_OBSERVED\',\'VIRTUAL\')),\n                    last_observed_at TEXT,\n                    last_sync_run_id TEXT,\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL,\n                    FOREIGN KEY(monitored_stock_id)\n                        REFERENCES monitored_stock(id) ON DELETE RESTRICT,\n                    FOREIGN KEY(position_account_id)\n                        REFERENCES position_account(id) ON DELETE RESTRICT,\n                    FOREIGN KEY(last_sync_run_id)\n                        REFERENCES account_sync_run(id) ON DELETE RESTRICT\n                );\n\n                CREATE UNIQUE INDEX IF NOT EXISTS ux_holding_position_open_stock_account\n                    ON holding_position(monitored_stock_id, position_account_id)\n                    WHERE status=\'OPEN\';\n\n                CREATE INDEX IF NOT EXISTS idx_holding_position_stock_status\n                    ON holding_position(monitored_stock_id, status);\n\n                CREATE TABLE IF NOT EXISTS holding_position_event (\n                    id TEXT PRIMARY KEY,\n                    position_id TEXT NOT NULL,\n                    event_type TEXT NOT NULL\n                        CHECK(event_type IN (\n                            \'BUY\',\'SELL\',\'CORRECTION\',\'BALANCE_OBSERVED\',\'RECONCILED\'\n                        )),\n                    quantity_delta TEXT,\n                    unit_price TEXT,\n                    before_quantity TEXT,\n                    after_quantity TEXT,\n                    before_average_price TEXT,\n                    after_average_price TEXT,\n                    observed_at TEXT,\n                    effective_at TEXT,\n                    analysis_revision_id TEXT,\n                    account_sync_run_id TEXT,\n                    external_event_key TEXT,\n                    note TEXT,\n                    created_at TEXT NOT NULL,\n                    FOREIGN KEY(position_id)\n                        REFERENCES holding_position(id) ON DELETE RESTRICT,\n                    FOREIGN KEY(analysis_revision_id)\n                        REFERENCES stock_analysis_revision(id) ON DELETE RESTRICT,\n                    FOREIGN KEY(account_sync_run_id)\n                        REFERENCES account_sync_run(id) ON DELETE RESTRICT\n                );\n\n                CREATE UNIQUE INDEX IF NOT EXISTS ux_holding_event_external_key\n                    ON holding_position_event(position_id, external_event_key)\n                    WHERE external_event_key IS NOT NULL;\n\n                CREATE INDEX IF NOT EXISTS idx_holding_event_position_created\n                    ON holding_position_event(position_id, created_at, id);\n\n                CREATE TRIGGER IF NOT EXISTS trg_holding_position_event_no_update\n                BEFORE UPDATE ON holding_position_event\n                BEGIN\n                    SELECT RAISE(ABORT, \'holding_position_event is append-only\');\n                END;\n\n                CREATE TRIGGER IF NOT EXISTS trg_holding_position_event_no_delete\n                BEFORE DELETE ON holding_position_event\n                BEGIN\n                    SELECT RAISE(ABORT, \'holding_position_event is append-only\');\n                END;\n                """\n            )\n\n    @staticmethod\n    def _account_from_row(row: sqlite3.Row) -> PositionAccount:\n        return PositionAccount(\n            id=row["id"],\n            provider=row["provider"],\n            account_kind=row["account_kind"],\n            broker_environment=row["broker_environment"],\n            external_account_fingerprint=row["external_account_fingerprint"],\n            display_name=row["display_name"],\n            status=row["status"],\n            created_at=row["created_at"],\n            updated_at=row["updated_at"],\n        )\n\n    @staticmethod\n    def _stock_from_row(row: sqlite3.Row) -> MonitoredStock:\n        return MonitoredStock(\n            id=row["id"],\n            market=row["market"],\n            ticker=row["ticker"],\n            name=row["name"],\n            watch_enabled=bool(row["watch_enabled"]),\n            archived_at=row["archived_at"],\n            created_at=row["created_at"],\n            updated_at=row["updated_at"],\n        )\n\n    @staticmethod\n    def _sync_from_row(row: sqlite3.Row) -> AccountSyncRun:\n        return AccountSyncRun(\n            id=row["id"],\n            position_account_id=row["position_account_id"],\n            status=row["status"],\n            started_at=row["started_at"],\n            completed_at=row["completed_at"],\n            is_complete=bool(row["is_complete"]),\n            observed_at=row["observed_at"],\n            page_count=int(row["page_count"] or 0),\n            holding_count=int(row["holding_count"] or 0),\n            error_code=row["error_code"],\n            error_message=row["error_message"],\n            created_at=row["created_at"],\n            updated_at=row["updated_at"],\n        )\n\n    @staticmethod\n    def _position_from_row(row: sqlite3.Row) -> HoldingPosition:\n        return HoldingPosition(\n            id=row["id"],\n            monitored_stock_id=row["monitored_stock_id"],\n            position_account_id=row["position_account_id"],\n            status=row["status"],\n            opened_at=row["opened_at"],\n            closed_at=row["closed_at"],\n            current_quantity=_decimal_value(row["current_quantity"]) or Decimal("0"),\n            current_average_price=_decimal_value(row["current_average_price"]),\n            current_cost_basis=_decimal_value(row["current_cost_basis"]),\n            opened_reason=row["opened_reason"],\n            last_observed_at=row["last_observed_at"],\n            last_sync_run_id=row["last_sync_run_id"],\n            created_at=row["created_at"],\n            updated_at=row["updated_at"],\n        )\n\n    @staticmethod\n    def _event_from_row(row: sqlite3.Row) -> HoldingPositionEvent:\n        return HoldingPositionEvent(\n            id=row["id"],\n            position_id=row["position_id"],\n            event_type=row["event_type"],\n            quantity_delta=_decimal_value(row["quantity_delta"]),\n            unit_price=_decimal_value(row["unit_price"]),\n            before_quantity=_decimal_value(row["before_quantity"]),\n            after_quantity=_decimal_value(row["after_quantity"]),\n            before_average_price=_decimal_value(row["before_average_price"]),\n            after_average_price=_decimal_value(row["after_average_price"]),\n            observed_at=row["observed_at"],\n            effective_at=row["effective_at"],\n            analysis_revision_id=row["analysis_revision_id"],\n            account_sync_run_id=row["account_sync_run_id"],\n            external_event_key=row["external_event_key"],\n            note=row["note"],\n            created_at=row["created_at"],\n        )\n\n    @staticmethod\n    def _day_from_row(row: sqlite3.Row) -> StockAnalysisDay:\n        return StockAnalysisDay(\n            id=row["id"],\n            monitored_stock_id=row["monitored_stock_id"],\n            market_date=row["market_date"],\n            current_revision_id=row["current_revision_id"],\n            created_at=row["created_at"],\n            updated_at=row["updated_at"],\n        )\n\n    @staticmethod\n    def _revision_from_row(row: sqlite3.Row) -> StockAnalysisRevision:\n        return StockAnalysisRevision(\n            id=row["id"],\n            analysis_day_id=row["analysis_day_id"],\n            revision_no=int(row["revision_no"]),\n            input_fingerprint=row["input_fingerprint"],\n            strategy_key=row["strategy_key"],\n            action_state=row["action_state"],\n            risk_state=row["risk_state"],\n            reference_price=_decimal_value(row["reference_price"]),\n            stop_price=_decimal_value(row["stop_price"]),\n            target1_price=_decimal_value(row["target1_price"]),\n            target2_price=_decimal_value(row["target2_price"]),\n            scanner_version=row["scanner_version"],\n            analysis_engine_version=row["analysis_engine_version"],\n            policy_version=row["policy_version"],\n            source_versions=_json_value(row["source_versions_json"]),\n            snapshot=_json_value(row["snapshot_json"]),\n            revision_reason=row["revision_reason"],\n            computed_at=row["computed_at"],\n            created_at=row["created_at"],\n        )\n\n    def create_position_account(\n        self,\n        *,\n        provider: str,\n        account_kind: str,\n        display_name: str,\n        broker_environment: str | None = None,\n        external_account_fingerprint: str | None = None,\n    ) -> PositionAccount:\n        provider_value = provider.strip().upper()\n        kind = account_kind.strip().upper()\n        environment = broker_environment.strip().upper() if broker_environment else None\n        name = display_name.strip()\n        fingerprint = (\n            external_account_fingerprint.strip().lower()\n            if external_account_fingerprint\n            else None\n        )\n\n        if not provider_value or not name:\n            raise HoldingsCatalogError(\n                "HOLD_ACCOUNT_REQUIRED",\n                "provider와 display_name이 필요합니다.",\n            )\n        if kind not in ACCOUNT_KINDS:\n            raise HoldingsCatalogError("HOLD_ACCOUNT_KIND_INVALID", f"지원하지 않는 account_kind입니다: {kind}")\n        if environment is not None and environment not in BROKER_ENVIRONMENTS:\n            raise HoldingsCatalogError("HOLD_BROKER_ENV_INVALID", f"지원하지 않는 broker_environment입니다: {environment}")\n        if kind == "BROKER" and fingerprint is None:\n            raise HoldingsCatalogError(\n                "HOLD_ACCOUNT_FINGERPRINT_REQUIRED",\n                "BROKER 계좌에는 외부 계좌 fingerprint가 필요합니다.",\n            )\n        if fingerprint is not None and not _HEX64.fullmatch(fingerprint):\n            raise HoldingsCatalogError(\n                "HOLD_ACCOUNT_FINGERPRINT_INVALID",\n                "외부 계좌 fingerprint는 SHA-256 64자리 hex 형식이어야 합니다.",\n            )\n\n        now = _now()\n        account_id = str(uuid4())\n        try:\n            with self.connect() as conn:\n                conn.execute(\n                    """\n                    INSERT INTO position_account(\n                        id,provider,account_kind,broker_environment,\n                        external_account_fingerprint,display_name,status,created_at,updated_at\n                    ) VALUES(?,?,?,?,?,?,?,?,?)\n                    """,\n                    (\n                        account_id,\n                        provider_value,\n                        kind,\n                        environment,\n                        fingerprint,\n                        name,\n                        "ACTIVE",\n                        now,\n                        now,\n                    ),\n                )\n                row = conn.execute(\n                    "SELECT * FROM position_account WHERE id=?",\n                    (account_id,),\n                ).fetchone()\n        except sqlite3.IntegrityError as exc:\n            raise HoldingsCatalogError(\n                "HOLD_ACCOUNT_DUPLICATE",\n                "이미 등록된 외부 계좌입니다.",\n            ) from exc\n        return self._account_from_row(row)\n\n    def get_position_account(self, account_id: str) -> PositionAccount | None:\n        with self.connect() as conn:\n            row = conn.execute(\n                "SELECT * FROM position_account WHERE id=?",\n                (account_id,),\n            ).fetchone()\n        return self._account_from_row(row) if row else None\n\n    def create_monitored_stock(\n        self,\n        *,\n        market: str,\n        ticker: str,\n        name: str,\n        watch_enabled: bool = True,\n    ) -> MonitoredStock:\n        market_value = market.strip().upper()\n        ticker_value = ticker.strip()\n        name_value = name.strip()\n        if not market_value or not ticker_value or not name_value:\n            raise HoldingsCatalogError(\n                "HOLD_STOCK_REQUIRED",\n                "market, ticker, name이 필요합니다.",\n            )\n\n        now = _now()\n        stock_id = str(uuid4())\n        try:\n            with self.connect() as conn:\n                conn.execute(\n                    """\n                    INSERT INTO monitored_stock(\n                        id,market,ticker,name,watch_enabled,archived_at,created_at,updated_at\n                    ) VALUES(?,?,?,?,?,?,?,?)\n                    """,\n                    (\n                        stock_id,\n                        market_value,\n                        ticker_value,\n                        name_value,\n                        int(watch_enabled),\n                        None,\n                        now,\n                        now,\n                    ),\n                )\n                row = conn.execute(\n                    "SELECT * FROM monitored_stock WHERE id=?",\n                    (stock_id,),\n                ).fetchone()\n        except sqlite3.IntegrityError as exc:\n            raise HoldingsCatalogError(\n                "HOLD_STOCK_DUPLICATE",\n                f"이미 등록된 종목입니다: {market_value}/{ticker_value}",\n            ) from exc\n        return self._stock_from_row(row)\n\n    def get_monitored_stock(self, stock_id: str) -> MonitoredStock | None:\n        with self.connect() as conn:\n            row = conn.execute(\n                "SELECT * FROM monitored_stock WHERE id=?",\n                (stock_id,),\n            ).fetchone()\n        return self._stock_from_row(row) if row else None\n\n    def list_monitored_stocks(self, *, include_archived: bool = False) -> list[MonitoredStock]:\n        with self.connect() as conn:\n            if include_archived:\n                rows = conn.execute(\n                    "SELECT * FROM monitored_stock ORDER BY market,ticker"\n                ).fetchall()\n            else:\n                rows = conn.execute(\n                    "SELECT * FROM monitored_stock WHERE archived_at IS NULL ORDER BY market,ticker"\n                ).fetchall()\n        return [self._stock_from_row(row) for row in rows]\n\n    def set_watch_enabled(self, stock_id: str, enabled: bool) -> MonitoredStock:\n        now = _now()\n        with self.connect() as conn:\n            cursor = conn.execute(\n                "UPDATE monitored_stock SET watch_enabled=?,updated_at=? WHERE id=?",\n                (int(enabled), now, stock_id),\n            )\n            if cursor.rowcount != 1:\n                raise HoldingsCatalogError("HOLD_STOCK_NOT_FOUND", "종목을 찾을 수 없습니다.")\n            row = conn.execute(\n                "SELECT * FROM monitored_stock WHERE id=?",\n                (stock_id,),\n            ).fetchone()\n        return self._stock_from_row(row)\n\n    def archive_monitored_stock(self, stock_id: str) -> MonitoredStock:\n        now = _now()\n        with self.connect() as conn:\n            cursor = conn.execute(\n                """\n                UPDATE monitored_stock\n                SET archived_at=COALESCE(archived_at,?),updated_at=?\n                WHERE id=?\n                """,\n                (now, now, stock_id),\n            )\n            if cursor.rowcount != 1:\n                raise HoldingsCatalogError("HOLD_STOCK_NOT_FOUND", "종목을 찾을 수 없습니다.")\n            row = conn.execute(\n                "SELECT * FROM monitored_stock WHERE id=?",\n                (stock_id,),\n            ).fetchone()\n        return self._stock_from_row(row)\n\n    def open_position(\n        self,\n        *,\n        monitored_stock_id: str,\n        position_account_id: str,\n        opened_reason: str,\n        opened_at: str | None = None,\n        current_quantity: Decimal | int | float | str = "0",\n        current_average_price: Decimal | int | float | str | None = None,\n        current_cost_basis: Decimal | int | float | str | None = None,\n    ) -> HoldingPosition:\n        reason = opened_reason.strip().upper()\n        if reason not in POSITION_OPEN_REASONS:\n            raise HoldingsCatalogError(\n                "HOLD_POSITION_REASON_INVALID",\n                f"지원하지 않는 opened_reason입니다: {reason}",\n            )\n        quantity = _decimal_text(current_quantity)\n        if Decimal(quantity or "0") < 0:\n            raise HoldingsCatalogError(\n                "HOLD_POSITION_QUANTITY_INVALID",\n                "보유 수량은 음수일 수 없습니다.",\n            )\n\n        now = _now()\n        position_id = str(uuid4())\n        try:\n            with self.connect() as conn:\n                conn.execute(\n                    """\n                    INSERT INTO holding_position(\n                        id,monitored_stock_id,position_account_id,status,\n                        opened_at,closed_at,current_quantity,current_average_price,\n                        current_cost_basis,opened_reason,last_observed_at,last_sync_run_id,\n                        created_at,updated_at\n                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)\n                    """,\n                    (\n                        position_id,\n                        monitored_stock_id,\n                        position_account_id,\n                        "OPEN",\n                        opened_at or now,\n                        None,\n                        quantity,\n                        _decimal_text(current_average_price),\n                        _decimal_text(current_cost_basis),\n                        reason,\n                        None,\n                        None,\n                        now,\n                        now,\n                    ),\n                )\n                row = conn.execute(\n                    "SELECT * FROM holding_position WHERE id=?",\n                    (position_id,),\n                ).fetchone()\n        except sqlite3.IntegrityError as exc:\n            message = str(exc).lower()\n            if "ux_holding_position_open_stock_account" in message or "unique constraint failed" in message:\n                raise HoldingsCatalogError(\n                    "HOLD_OPEN_POSITION_DUPLICATE",\n                    "같은 종목과 계좌에는 열린 Position을 하나만 둘 수 있습니다.",\n                ) from exc\n            raise HoldingsCatalogError(\n                "HOLD_POSITION_FK_INVALID",\n                "종목 또는 계좌 참조가 유효하지 않습니다.",\n            ) from exc\n        return self._position_from_row(row)\n\n    def get_position(self, position_id: str) -> HoldingPosition | None:\n        with self.connect() as conn:\n            row = conn.execute(\n                "SELECT * FROM holding_position WHERE id=?",\n                (position_id,),\n            ).fetchone()\n        return self._position_from_row(row) if row else None\n\n    def list_positions(\n        self,\n        monitored_stock_id: str,\n        *,\n        status: str | None = None,\n    ) -> list[HoldingPosition]:\n        with self.connect() as conn:\n            if status is None:\n                rows = conn.execute(\n                    """\n                    SELECT * FROM holding_position\n                    WHERE monitored_stock_id=?\n                    ORDER BY opened_at,id\n                    """,\n                    (monitored_stock_id,),\n                ).fetchall()\n            else:\n                status_value = status.strip().upper()\n                if status_value not in POSITION_STATUSES:\n                    raise HoldingsCatalogError(\n                        "HOLD_POSITION_STATUS_INVALID",\n                        f"지원하지 않는 Position 상태입니다: {status}",\n                    )\n                rows = conn.execute(\n                    """\n                    SELECT * FROM holding_position\n                    WHERE monitored_stock_id=? AND status=?\n                    ORDER BY opened_at,id\n                    """,\n                    (monitored_stock_id, status_value),\n                ).fetchall()\n        return [self._position_from_row(row) for row in rows]\n\n    def close_position(\n        self,\n        position_id: str,\n        *,\n        closed_at: str | None = None,\n    ) -> HoldingPosition:\n        now = _now()\n        with self.connect() as conn:\n            cursor = conn.execute(\n                """\n                UPDATE holding_position\n                SET status=\'CLOSED\',closed_at=?,updated_at=?\n                WHERE id=? AND status=\'OPEN\'\n                """,\n                (closed_at or now, now, position_id),\n            )\n            if cursor.rowcount != 1:\n                raise HoldingsCatalogError(\n                    "HOLD_OPEN_POSITION_NOT_FOUND",\n                    "열린 Position을 찾을 수 없습니다.",\n                )\n            row = conn.execute(\n                "SELECT * FROM holding_position WHERE id=?",\n                (position_id,),\n            ).fetchone()\n        return self._position_from_row(row)\n\n    def append_position_event(\n        self,\n        *,\n        position_id: str,\n        event_type: str,\n        quantity_delta: Decimal | int | float | str | None = None,\n        unit_price: Decimal | int | float | str | None = None,\n        before_quantity: Decimal | int | float | str | None = None,\n        after_quantity: Decimal | int | float | str | None = None,\n        before_average_price: Decimal | int | float | str | None = None,\n        after_average_price: Decimal | int | float | str | None = None,\n        observed_at: str | None = None,\n        effective_at: str | None = None,\n        analysis_revision_id: str | None = None,\n        account_sync_run_id: str | None = None,\n        external_event_key: str | None = None,\n        note: str | None = None,\n    ) -> HoldingPositionEvent:\n        kind = event_type.strip().upper()\n        if kind not in POSITION_EVENT_TYPES:\n            raise HoldingsCatalogError(\n                "HOLD_EVENT_TYPE_INVALID",\n                f"지원하지 않는 Position Event입니다: {kind}",\n            )\n\n        now = _now()\n        event_id = str(uuid4())\n        try:\n            with self.connect() as conn:\n                conn.execute(\n                    """\n                    INSERT INTO holding_position_event(\n                        id,position_id,event_type,quantity_delta,unit_price,\n                        before_quantity,after_quantity,before_average_price,\n                        after_average_price,observed_at,effective_at,\n                        analysis_revision_id,account_sync_run_id,\n                        external_event_key,note,created_at\n                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)\n                    """,\n                    (\n                        event_id,\n                        position_id,\n                        kind,\n                        _decimal_text(quantity_delta),\n                        _decimal_text(unit_price),\n                        _decimal_text(before_quantity),\n                        _decimal_text(after_quantity),\n                        _decimal_text(before_average_price),\n                        _decimal_text(after_average_price),\n                        observed_at,\n                        effective_at,\n                        analysis_revision_id,\n                        account_sync_run_id,\n                        external_event_key.strip() if external_event_key else None,\n                        note,\n                        now,\n                    ),\n                )\n                row = conn.execute(\n                    "SELECT * FROM holding_position_event WHERE id=?",\n                    (event_id,),\n                ).fetchone()\n        except sqlite3.IntegrityError as exc:\n            if "unique constraint failed" in str(exc).lower():\n                raise HoldingsCatalogError(\n                    "HOLD_EVENT_DUPLICATE",\n                    "이미 기록된 외부 Position Event입니다.",\n                ) from exc\n            raise HoldingsCatalogError(\n                "HOLD_EVENT_REFERENCE_INVALID",\n                "Position Event의 참조가 유효하지 않습니다.",\n            ) from exc\n        return self._event_from_row(row)\n\n    def list_position_events(self, position_id: str) -> list[HoldingPositionEvent]:\n        with self.connect() as conn:\n            rows = conn.execute(\n                """\n                SELECT * FROM holding_position_event\n                WHERE position_id=?\n                ORDER BY created_at,id\n                """,\n                (position_id,),\n            ).fetchall()\n        return [self._event_from_row(row) for row in rows]\n\n    def start_sync_run(\n        self,\n        *,\n        position_account_id: str,\n        observed_at: str | None = None,\n    ) -> AccountSyncRun:\n        now = _now()\n        sync_id = str(uuid4())\n        try:\n            with self.connect() as conn:\n                conn.execute(\n                    """\n                    INSERT INTO account_sync_run(\n                        id,position_account_id,status,started_at,completed_at,\n                        is_complete,observed_at,page_count,holding_count,\n                        error_code,error_message,created_at,updated_at\n                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)\n                    """,\n                    (\n                        sync_id,\n                        position_account_id,\n                        "RUNNING",\n                        now,\n                        None,\n                        0,\n                        observed_at,\n                        0,\n                        0,\n                        None,\n                        None,\n                        now,\n                        now,\n                    ),\n                )\n                row = conn.execute(\n                    "SELECT * FROM account_sync_run WHERE id=?",\n                    (sync_id,),\n                ).fetchone()\n        except sqlite3.IntegrityError as exc:\n            raise HoldingsCatalogError(\n                "HOLD_SYNC_ACCOUNT_INVALID",\n                "동기화 대상 계좌를 찾을 수 없습니다.",\n            ) from exc\n        return self._sync_from_row(row)\n\n    def complete_sync_run(\n        self,\n        sync_run_id: str,\n        *,\n        observed_at: str,\n        page_count: int,\n        holding_count: int,\n    ) -> AccountSyncRun:\n        if page_count < 0 or holding_count < 0:\n            raise HoldingsCatalogError(\n                "HOLD_SYNC_COUNT_INVALID",\n                "동기화 count는 음수일 수 없습니다.",\n            )\n        now = _now()\n        with self.connect() as conn:\n            cursor = conn.execute(\n                """\n                UPDATE account_sync_run\n                SET status=\'COMPLETED\',completed_at=?,is_complete=1,\n                    observed_at=?,page_count=?,holding_count=?,\n                    error_code=NULL,error_message=NULL,updated_at=?\n                WHERE id=? AND status=\'RUNNING\'\n                """,\n                (\n                    now,\n                    observed_at,\n                    int(page_count),\n                    int(holding_count),\n                    now,\n                    sync_run_id,\n                ),\n            )\n            if cursor.rowcount != 1:\n                raise HoldingsCatalogError(\n                    "HOLD_SYNC_RUNNING_NOT_FOUND",\n                    "실행 중인 동기화 기록을 찾을 수 없습니다.",\n                )\n            row = conn.execute(\n                "SELECT * FROM account_sync_run WHERE id=?",\n                (sync_run_id,),\n            ).fetchone()\n        return self._sync_from_row(row)\n\n    def fail_sync_run(\n        self,\n        sync_run_id: str,\n        *,\n        error_code: str,\n        error_message: str,\n    ) -> AccountSyncRun:\n        now = _now()\n        with self.connect() as conn:\n            cursor = conn.execute(\n                """\n                UPDATE account_sync_run\n                SET status=\'FAILED\',completed_at=?,is_complete=0,\n                    error_code=?,error_message=?,updated_at=?\n                WHERE id=? AND status=\'RUNNING\'\n                """,\n                (now, error_code, error_message, now, sync_run_id),\n            )\n            if cursor.rowcount != 1:\n                raise HoldingsCatalogError(\n                    "HOLD_SYNC_RUNNING_NOT_FOUND",\n                    "실행 중인 동기화 기록을 찾을 수 없습니다.",\n                )\n            row = conn.execute(\n                "SELECT * FROM account_sync_run WHERE id=?",\n                (sync_run_id,),\n            ).fetchone()\n        return self._sync_from_row(row)\n\n    def get_or_create_analysis_day(\n        self,\n        *,\n        monitored_stock_id: str,\n        market_date: str,\n    ) -> StockAnalysisDay:\n        date_value = market_date.strip()\n        if not date_value:\n            raise HoldingsCatalogError(\n                "HOLD_ANALYSIS_DATE_REQUIRED",\n                "market_date가 필요합니다.",\n            )\n        with self.connect() as conn:\n            existing = conn.execute(\n                """\n                SELECT * FROM stock_analysis_day\n                WHERE monitored_stock_id=? AND market_date=?\n                """,\n                (monitored_stock_id, date_value),\n            ).fetchone()\n            if existing is not None:\n                return self._day_from_row(existing)\n\n            now = _now()\n            day_id = str(uuid4())\n            try:\n                conn.execute(\n                    """\n                    INSERT INTO stock_analysis_day(\n                        id,monitored_stock_id,market_date,current_revision_id,\n                        created_at,updated_at\n                    ) VALUES(?,?,?,?,?,?)\n                    """,\n                    (\n                        day_id,\n                        monitored_stock_id,\n                        date_value,\n                        None,\n                        now,\n                        now,\n                    ),\n                )\n            except sqlite3.IntegrityError as exc:\n                raise HoldingsCatalogError(\n                    "HOLD_ANALYSIS_STOCK_INVALID",\n                    "분석 대상 종목을 찾을 수 없습니다.",\n                ) from exc\n            row = conn.execute(\n                "SELECT * FROM stock_analysis_day WHERE id=?",\n                (day_id,),\n            ).fetchone()\n        return self._day_from_row(row)\n\n    def append_analysis_revision(\n        self,\n        *,\n        analysis_day_id: str,\n        input_fingerprint: str,\n        strategy_key: str | None,\n        action_state: str | None,\n        risk_state: str | None,\n        reference_price: Decimal | int | float | str | None,\n        stop_price: Decimal | int | float | str | None,\n        target1_price: Decimal | int | float | str | None,\n        target2_price: Decimal | int | float | str | None,\n        scanner_version: str | None,\n        analysis_engine_version: str | None,\n        policy_version: str | None,\n        source_versions: Any,\n        snapshot: Any,\n        revision_reason: str | None = None,\n        computed_at: str | None = None,\n    ) -> StockAnalysisRevision:\n        fingerprint = input_fingerprint.strip()\n        if not fingerprint:\n            raise HoldingsCatalogError(\n                "HOLD_ANALYSIS_FINGERPRINT_REQUIRED",\n                "input_fingerprint가 필요합니다.",\n            )\n\n        with self.connect() as conn:\n            existing = conn.execute(\n                """\n                SELECT * FROM stock_analysis_revision\n                WHERE analysis_day_id=? AND input_fingerprint=?\n                """,\n                (analysis_day_id, fingerprint),\n            ).fetchone()\n            if existing is not None:\n                return self._revision_from_row(existing)\n\n            day = conn.execute(\n                "SELECT id FROM stock_analysis_day WHERE id=?",\n                (analysis_day_id,),\n            ).fetchone()\n            if day is None:\n                raise HoldingsCatalogError(\n                    "HOLD_ANALYSIS_DAY_NOT_FOUND",\n                    "분석일을 찾을 수 없습니다.",\n                )\n\n            next_revision = int(\n                conn.execute(\n                    """\n                    SELECT COALESCE(MAX(revision_no),0)+1 AS next_revision\n                    FROM stock_analysis_revision\n                    WHERE analysis_day_id=?\n                    """,\n                    (analysis_day_id,),\n                ).fetchone()["next_revision"]\n            )\n            now = _now()\n            revision_id = str(uuid4())\n            conn.execute(\n                """\n                INSERT INTO stock_analysis_revision(\n                    id,analysis_day_id,revision_no,input_fingerprint,\n                    strategy_key,action_state,risk_state,\n                    reference_price,stop_price,target1_price,target2_price,\n                    scanner_version,analysis_engine_version,policy_version,\n                    source_versions_json,snapshot_json,revision_reason,\n                    computed_at,created_at\n                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)\n                """,\n                (\n                    revision_id,\n                    analysis_day_id,\n                    next_revision,\n                    fingerprint,\n                    strategy_key,\n                    action_state,\n                    risk_state,\n                    _decimal_text(reference_price),\n                    _decimal_text(stop_price),\n                    _decimal_text(target1_price),\n                    _decimal_text(target2_price),\n                    scanner_version,\n                    analysis_engine_version,\n                    policy_version,\n                    _json_text(source_versions),\n                    _json_text(snapshot),\n                    revision_reason,\n                    computed_at or now,\n                    now,\n                ),\n            )\n            row = conn.execute(\n                "SELECT * FROM stock_analysis_revision WHERE id=?",\n                (revision_id,),\n            ).fetchone()\n        return self._revision_from_row(row)\n\n    def promote_current_revision(\n        self,\n        *,\n        analysis_day_id: str,\n        revision_id: str,\n    ) -> StockAnalysisDay:\n        now = _now()\n        with self.connect() as conn:\n            revision = conn.execute(\n                """\n                SELECT id FROM stock_analysis_revision\n                WHERE id=? AND analysis_day_id=?\n                """,\n                (revision_id, analysis_day_id),\n            ).fetchone()\n            if revision is None:\n                raise HoldingsCatalogError(\n                    "HOLD_ANALYSIS_REVISION_MISMATCH",\n                    "해당 분석일의 revision이 아닙니다.",\n                )\n            cursor = conn.execute(\n                """\n                UPDATE stock_analysis_day\n                SET current_revision_id=?,updated_at=?\n                WHERE id=?\n                """,\n                (revision_id, now, analysis_day_id),\n            )\n            if cursor.rowcount != 1:\n                raise HoldingsCatalogError(\n                    "HOLD_ANALYSIS_DAY_NOT_FOUND",\n                    "분석일을 찾을 수 없습니다.",\n                )\n            row = conn.execute(\n                "SELECT * FROM stock_analysis_day WHERE id=?",\n                (analysis_day_id,),\n            ).fetchone()\n        return self._day_from_row(row)\n\n    def get_current_revision(\n        self,\n        analysis_day_id: str,\n    ) -> StockAnalysisRevision | None:\n        with self.connect() as conn:\n            row = conn.execute(\n                """\n                SELECT r.*\n                FROM stock_analysis_day d\n                JOIN stock_analysis_revision r ON r.id=d.current_revision_id\n                WHERE d.id=?\n                """,\n                (analysis_day_id,),\n            ).fetchone()\n        return self._revision_from_row(row) if row else None\n'
TEST_CONTENT = 'from __future__ import annotations\n\nimport sqlite3\nfrom decimal import Decimal\n\nimport pytest\n\nfrom app.holdings import HoldingsCatalog, HoldingsCatalogError, account_fingerprint\n\n\n@pytest.fixture()\ndef catalog(tmp_path):\n    value = HoldingsCatalog(tmp_path / "holdings.db")\n    value.initialize()\n    return value\n\n\ndef _manual_account(catalog: HoldingsCatalog, name: str = "수동 계좌"):\n    return catalog.create_position_account(\n        provider="MANUAL",\n        account_kind="MANUAL",\n        display_name=name,\n    )\n\n\ndef _virtual_account(catalog: HoldingsCatalog):\n    return catalog.create_position_account(\n        provider="VIRTUAL",\n        account_kind="VIRTUAL",\n        display_name="가상 계좌",\n    )\n\n\ndef _stock(catalog: HoldingsCatalog):\n    return catalog.create_monitored_stock(\n        market="KOSPI",\n        ticker="005930",\n        name="삼성전자",\n    )\n\n\ndef _revision(catalog: HoldingsCatalog, stock_id: str, fingerprint: str = "fp-1"):\n    day = catalog.get_or_create_analysis_day(\n        monitored_stock_id=stock_id,\n        market_date="2026-09-22",\n    )\n    revision = catalog.append_analysis_revision(\n        analysis_day_id=day.id,\n        input_fingerprint=fingerprint,\n        strategy_key="trend_recovery",\n        action_state="WATCH",\n        risk_state="READY",\n        reference_price="277500",\n        stop_price="270000",\n        target1_price="285000",\n        target2_price="295000",\n        scanner_version="0.21.3.7",\n        analysis_engine_version="HOLD_TEST",\n        policy_version="TEST",\n        source_versions={"market_store": "fixture"},\n        snapshot={"strategy": "trend_recovery"},\n    )\n    return day, revision\n\n\ndef test_monitored_stock_unique_and_watch_independent_from_position(catalog):\n    stock = _stock(catalog)\n    account = _manual_account(catalog)\n\n    updated = catalog.set_watch_enabled(stock.id, False)\n    assert updated.watch_enabled is False\n\n    position = catalog.open_position(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        opened_reason="MANUAL",\n        current_quantity="10",\n        current_average_price="70000",\n    )\n    assert position.status == "OPEN"\n    assert catalog.get_monitored_stock(stock.id).watch_enabled is False\n\n    with pytest.raises(HoldingsCatalogError) as exc_info:\n        _stock(catalog)\n    assert exc_info.value.code == "HOLD_STOCK_DUPLICATE"\n\n\ndef test_raw_broker_account_number_is_not_persisted(catalog):\n    raw_account = "12345678"\n    fingerprint = account_fingerprint(\n        provider="KIS",\n        broker_environment="REAL",\n        account_number=raw_account,\n        product_code="01",\n    )\n    account = catalog.create_position_account(\n        provider="KIS",\n        account_kind="BROKER",\n        broker_environment="REAL",\n        external_account_fingerprint=fingerprint,\n        display_name="한국투자증권",\n    )\n\n    assert account.external_account_fingerprint == fingerprint\n    assert raw_account.encode() not in catalog.db_path.read_bytes()\n\n\ndef test_multiple_accounts_allowed_but_only_one_open_position_per_stock_account(catalog):\n    stock = _stock(catalog)\n    manual = _manual_account(catalog)\n    virtual = _virtual_account(catalog)\n\n    first = catalog.open_position(\n        monitored_stock_id=stock.id,\n        position_account_id=manual.id,\n        opened_reason="MANUAL",\n        current_quantity="10",\n    )\n    second = catalog.open_position(\n        monitored_stock_id=stock.id,\n        position_account_id=virtual.id,\n        opened_reason="VIRTUAL",\n        current_quantity="20",\n    )\n    assert first.position_account_id != second.position_account_id\n\n    with pytest.raises(HoldingsCatalogError) as exc_info:\n        catalog.open_position(\n            monitored_stock_id=stock.id,\n            position_account_id=manual.id,\n            opened_reason="MANUAL",\n        )\n    assert exc_info.value.code == "HOLD_OPEN_POSITION_DUPLICATE"\n\n\ndef test_closed_position_allows_new_holding_round(catalog):\n    stock = _stock(catalog)\n    account = _manual_account(catalog)\n    old = catalog.open_position(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        opened_reason="MANUAL",\n        current_quantity="1",\n    )\n    catalog.close_position(old.id)\n\n    new = catalog.open_position(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        opened_reason="MANUAL",\n        current_quantity="2",\n    )\n\n    assert new.id != old.id\n    assert len(catalog.list_positions(stock.id)) == 2\n    assert len(catalog.list_positions(stock.id, status="OPEN")) == 1\n\n\ndef test_position_event_is_append_only_and_supports_balance_observation(catalog):\n    stock = _stock(catalog)\n    account = _manual_account(catalog)\n    position = catalog.open_position(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        opened_reason="MANUAL",\n    )\n\n    event = catalog.append_position_event(\n        position_id=position.id,\n        event_type="BALANCE_OBSERVED",\n        before_quantity="100",\n        after_quantity="70",\n        observed_at="2026-09-22T10:00:00+09:00",\n    )\n    assert event.event_type == "BALANCE_OBSERVED"\n    assert event.before_quantity == Decimal("100")\n    assert event.after_quantity == Decimal("70")\n\n    with catalog.connect() as conn:\n        with pytest.raises(sqlite3.DatabaseError):\n            conn.execute(\n                "UPDATE holding_position_event SET note=\'changed\' WHERE id=?",\n                (event.id,),\n            )\n        with pytest.raises(sqlite3.DatabaseError):\n            conn.execute(\n                "DELETE FROM holding_position_event WHERE id=?",\n                (event.id,),\n            )\n\n\ndef test_sync_run_completed_and_failed_states(catalog):\n    account = _manual_account(catalog)\n\n    completed = catalog.start_sync_run(\n        position_account_id=account.id,\n        observed_at="2026-09-22T10:00:00+09:00",\n    )\n    completed = catalog.complete_sync_run(\n        completed.id,\n        observed_at="2026-09-22T10:00:01+09:00",\n        page_count=1,\n        holding_count=0,\n    )\n    assert completed.status == "COMPLETED"\n    assert completed.is_complete is True\n\n    failed = catalog.start_sync_run(position_account_id=account.id)\n    failed = catalog.fail_sync_run(\n        failed.id,\n        error_code="NETWORK",\n        error_message="test",\n    )\n    assert failed.status == "FAILED"\n    assert failed.is_complete is False\n\n\ndef test_analysis_day_is_idempotent(catalog):\n    stock = _stock(catalog)\n    first = catalog.get_or_create_analysis_day(\n        monitored_stock_id=stock.id,\n        market_date="2026-09-22",\n    )\n    second = catalog.get_or_create_analysis_day(\n        monitored_stock_id=stock.id,\n        market_date="2026-09-22",\n    )\n    assert second.id == first.id\n\n\ndef test_same_fingerprint_reuses_revision_and_new_input_adds_revision(catalog):\n    stock = _stock(catalog)\n    day, first = _revision(catalog, stock.id, "same")\n\n    same = catalog.append_analysis_revision(\n        analysis_day_id=day.id,\n        input_fingerprint="same",\n        strategy_key="different-value-that-must-not-overwrite",\n        action_state="READY",\n        risk_state="READY",\n        reference_price="999999",\n        stop_price=None,\n        target1_price=None,\n        target2_price=None,\n        scanner_version="different",\n        analysis_engine_version="different",\n        policy_version="different",\n        source_versions={},\n        snapshot={},\n    )\n    assert same.id == first.id\n    assert same.strategy_key == "trend_recovery"\n\n    second = catalog.append_analysis_revision(\n        analysis_day_id=day.id,\n        input_fingerprint="changed",\n        strategy_key="trend_following",\n        action_state="READY",\n        risk_state="READY",\n        reference_price="280000",\n        stop_price="270000",\n        target1_price="290000",\n        target2_price="300000",\n        scanner_version="0.21.3.7",\n        analysis_engine_version="HOLD_TEST",\n        policy_version="TEST",\n        source_versions={"market_store": "fixture-2"},\n        snapshot={"strategy": "trend_following"},\n        revision_reason="INPUT_CHANGED",\n    )\n    assert second.revision_no == 2\n\n\ndef test_revision_is_immutable_and_current_revision_can_move(catalog):\n    stock = _stock(catalog)\n    day, first = _revision(catalog, stock.id, "fp-1")\n    second = catalog.append_analysis_revision(\n        analysis_day_id=day.id,\n        input_fingerprint="fp-2",\n        strategy_key="trend_following",\n        action_state="READY",\n        risk_state="READY",\n        reference_price="280000",\n        stop_price=None,\n        target1_price=None,\n        target2_price=None,\n        scanner_version="0.21.3.7",\n        analysis_engine_version="HOLD_TEST",\n        policy_version="TEST",\n        source_versions={},\n        snapshot={},\n    )\n\n    catalog.promote_current_revision(\n        analysis_day_id=day.id,\n        revision_id=first.id,\n    )\n    assert catalog.get_current_revision(day.id).id == first.id\n\n    catalog.promote_current_revision(\n        analysis_day_id=day.id,\n        revision_id=second.id,\n    )\n    assert catalog.get_current_revision(day.id).id == second.id\n\n    with catalog.connect() as conn:\n        with pytest.raises(sqlite3.DatabaseError):\n            conn.execute(\n                "UPDATE stock_analysis_revision SET strategy_key=\'x\' WHERE id=?",\n                (first.id,),\n            )\n\n\ndef test_buy_event_keeps_original_analysis_revision_reference(catalog):\n    stock = _stock(catalog)\n    account = _manual_account(catalog)\n    position = catalog.open_position(\n        monitored_stock_id=stock.id,\n        position_account_id=account.id,\n        opened_reason="MANUAL",\n    )\n    day, first = _revision(catalog, stock.id, "fp-1")\n    catalog.promote_current_revision(\n        analysis_day_id=day.id,\n        revision_id=first.id,\n    )\n    event = catalog.append_position_event(\n        position_id=position.id,\n        event_type="BUY",\n        quantity_delta="10",\n        unit_price="70000",\n        analysis_revision_id=first.id,\n    )\n\n    second = catalog.append_analysis_revision(\n        analysis_day_id=day.id,\n        input_fingerprint="fp-2",\n        strategy_key="trend_following",\n        action_state="READY",\n        risk_state="READY",\n        reference_price="280000",\n        stop_price=None,\n        target1_price=None,\n        target2_price=None,\n        scanner_version="0.21.3.7",\n        analysis_engine_version="HOLD_TEST",\n        policy_version="TEST",\n        source_versions={},\n        snapshot={},\n    )\n    catalog.promote_current_revision(\n        analysis_day_id=day.id,\n        revision_id=second.id,\n    )\n\n    stored_event = catalog.list_position_events(position.id)[0]\n    assert stored_event.analysis_revision_id == first.id\n    assert catalog.get_current_revision(day.id).id == second.id\n\n\ndef test_foreign_keys_are_enforced(catalog):\n    account = _manual_account(catalog)\n\n    with pytest.raises(HoldingsCatalogError) as exc_info:\n        catalog.open_position(\n            monitored_stock_id="missing-stock",\n            position_account_id=account.id,\n            opened_reason="MANUAL",\n        )\n    assert exc_info.value.code == "HOLD_POSITION_FK_INVALID"\n'


def fail(message: str) -> None:
    raise RuntimeError(message)


def run(cmd: list[str], label: str) -> None:
    print()
    print(f"=== {label} ===")
    print(" ".join(cmd))
    result = subprocess.run(cmd, cwd=ROOT)
    if result.returncode != 0:
        fail(f"{label} failed with exit code {result.returncode}")


def main() -> int:
    print("PROJECT ROOT:", ROOT)
    print("HOLD.1-A Domain / Persistence")
    print("Scanner/Strategy/Risk/Market Store modified: NO")
    print("KIS integration modified: NO")
    print("Frontend/API modified: NO")

    for path in (INIT, DOMAIN, CATALOG, TEST):
        if path.exists():
            fail(f"Target already exists: {path}")

    compile(INIT_CONTENT, str(INIT), "exec")
    compile(DOMAIN_CONTENT, str(DOMAIN), "exec")
    compile(CATALOG_CONTENT, str(CATALOG), "exec")
    compile(TEST_CONTENT, str(TEST), "exec")

    HOLDINGS_DIR.mkdir(parents=True, exist_ok=True)
    created = []
    tests_passed = False
    try:
        INIT.write_text(INIT_CONTENT, encoding="utf-8", newline="\n")
        created.append(INIT)
        DOMAIN.write_text(DOMAIN_CONTENT, encoding="utf-8", newline="\n")
        created.append(DOMAIN)
        CATALOG.write_text(CATALOG_CONTENT, encoding="utf-8", newline="\n")
        created.append(CATALOG)
        TEST.write_text(TEST_CONTENT, encoding="utf-8", newline="\n")
        created.append(TEST)

        venv_python = ROOT / ".venv" / "Scripts" / "python.exe"
        python_exe = str(
            venv_python if venv_python.is_file() else Path(sys.executable)
        )

        run(
            [
                python_exe,
                "-m",
                "pytest",
                "backend/tests/test_holdings_catalog_hold1a.py",
                "-q",
            ],
            "HOLD.1-A persistence invariants",
        )

        kis_tests = [
            ROOT / "backend" / "tests" / "test_kis_client.py",
            ROOT / "backend" / "tests" / "test_kis_account.py",
            ROOT / "backend" / "tests" / "test_kis_quote.py",
            ROOT / "backend" / "tests" / "test_kis_websocket.py",
        ]
        existing_kis = [str(path.relative_to(ROOT)) for path in kis_tests if path.is_file()]
        if existing_kis:
            run(
                [python_exe, "-m", "pytest", *existing_kis, "-q"],
                "Existing KIS regression",
            )

        tests_passed = True

        smoke_code = """import sys
from pathlib import Path
from tempfile import TemporaryDirectory
sys.path.insert(0, 'backend')
from app.holdings import HoldingsCatalog

with TemporaryDirectory() as tmp:
    db = Path(tmp) / 'holdings.db'
    catalog = HoldingsCatalog(db)
    catalog.initialize()
    with catalog.connect() as conn:
        tables = [r['name'] for r in conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
        ).fetchall()]
    required = {
        'position_account',
        'monitored_stock',
        'holding_position',
        'holding_position_event',
        'account_sync_run',
        'stock_analysis_day',
        'stock_analysis_revision',
    }
    assert required.issubset(set(tables))
    print('HOLDINGS DB INIT: PASS')
    print('TABLES:', ', '.join(sorted(required)))
    print('RAW ACCOUNT NUMBER COLUMN: NO')
"""
        run([python_exe, "-c", smoke_code], "HOLD.1-A schema smoke")

        print()
        print("HOLD.1-A CLOSED")
        print("Added:")
        print(" - backend/app/holdings/__init__.py")
        print(" - backend/app/holdings/domain.py")
        print(" - backend/app/holdings/catalog.py")
        print(" - backend/tests/test_holdings_catalog_hold1a.py")
        print("Runtime DB default:")
        print(" - backend/runtime/holdings/holdings.db")
        print("Raw broker account number persisted: NO")
        print("Scanner/Strategy/Risk/Market Store modified: NO")
        print("KIS integration modified: NO")
        print("Frontend/API modified: NO")
        return 0

    except Exception:
        if not tests_passed:
            for path in reversed(created):
                if path.exists():
                    path.unlink()
            try:
                if HOLDINGS_DIR.exists() and not any(HOLDINGS_DIR.iterdir()):
                    HOLDINGS_DIR.rmdir()
            except OSError:
                pass
            print()
            print("FAILED — HOLD.1-A additions were restored because validation failed.")
        raise


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print()
        print(f"ERROR: {exc}", file=sys.stderr)
        raise SystemExit(1)
